import re
from decimal import Decimal, ROUND_HALF_UP

_UNITS = {
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'd': 86400, 'day': 86400, 'days': 86400,
    'w': 604800, 'wk': 604800, 'wks': 604800, 'week': 604800, 'weeks': 604800,
}

_NUM = r'\d+(?:\.\d+)?'
_COMPONENT = re.compile(r'(' + _NUM + r')\s*([A-Za-z]+)')
_COMPONENTS_FULL = re.compile(r'(?:\s*' + _NUM + r'\s*[A-Za-z]+\s*)+')
_ISO = re.compile(
    r'P(?:(' + _NUM + r')W)?(?:(' + _NUM + r')D)?'
    r'(?:T(?:(' + _NUM + r')H)?(?:(' + _NUM + r')M)?(?:(' + _NUM + r')S)?)?'
)
_CLOCK = re.compile(r'\d+(?::\d+){1,2}')


def _round(value: Decimal) -> int:
    return int(value.quantize(Decimal(1), rounding=ROUND_HALF_UP))


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    if s.isdigit():
        return int(s)

    if s.startswith('P'):
        if s == 'P' or s.endswith('T'):
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        m = _ISO.fullmatch(s)
        if not m:
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        weeks, days, hours, mins, secs = (Decimal(g) if g else Decimal(0) for g in m.groups())
        total = (weeks * 604800 + days * 86400 + hours * 3600
                 + mins * 60 + secs)
        return _round(total)

    if ':' in s:
        if not _CLOCK.fullmatch(s):
            raise ValueError(f"invalid clock duration: {text!r}")
        parts = [int(p) for p in s.split(':')]
        total = 0
        for p in parts:
            total = total * 60 + p
        return total

    if _COMPONENTS_FULL.fullmatch(s):
        total = Decimal(0)
        for num, unit in _COMPONENT.findall(s):
            key = unit.lower()
            if key not in _UNITS:
                raise ValueError(f"unknown unit: {unit!r}")
            total += Decimal(num) * _UNITS[key]
        return _round(total)

    raise ValueError(f"invalid duration: {text!r}")

